transforms.code:
assetId = value.get('assetId') if value else None
rows = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.asset.getAssets({'assetId': assetId or -1}) or [])
return rows[0] if rows else {}

if len(value['selected']) != 1: return []
rows = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.tooling.getPositions({'toolingAssetId': value['selected'][0]['toolingAssetId']}) or [])
return [{'toolingPositionId': r['toolingPositionId'], 'positionNumber': r['positionNumber'], 'positionType': r['positionType'],
		 'itemName': r['itemName'] or '', 'outputQty': r['outputQty'], 'isBlocked': bool(r['isBlocked']), 'blockReason': r['blockReason'] or ''}
		for r in rows if r['outputQty'] > 0]

assetPath = value['asset'].get('assetPath') if value['asset'] else None
start = None
if assetPath:
	try:
		qv = system.tag.readBlocking(['[kanoaMES]' + assetPath.replace('\\', '/') + '/OEE/Status/shiftStart'])[0]
		if qv.quality.isGood() and qv.value: start = qv.value
	except:
		start = None
return start or system.date.addHours(system.date.now(), -12)

security = value['security']
userCRUD = security['userCRUD'] if security else {}
assetPath = value['assetPath'] or ''
def allowed(right):
	entry = userCRUD.get(right, {}) if userCRUD else {}
	if not entry.get('enabled'): return False
	assets = entry.get('assets') or []
	return not assets or any(assetPath == a or assetPath.startswith(a + '\\') for a in assets)
admin = bool(userCRUD) and userCRUD.get('isGatewayAdmin')
return {'canOperate': bool(admin or allowed('operateAssets')), 'canConfigure': bool(admin or allowed('configureAssets'))}

if not value: return 'No asset'
if not value.get('usesTooling'): return "%s doesn't use tooling: turn on Uses tooling in the asset editor first." % value.get('assetName')
return 'Tooling on %s' % value.get('assetPath')

options = []
for tool in value['mounted']:
	for p in system.kanoa.utilities.convertDatasetToJSON(system.kanoa.tooling.getPositions({'toolingAssetId': tool['toolingAssetId']}) or []):
		if p['positionType'] == 'pocket' and p['heldToolingAssetId'] is None:
			options.append({'value': '%s:%s' % (tool['toolingAssetId'], p['toolingPositionId']),
							'label': '%s, pocket %s%s' % (tool['tool'].strip(), p['positionNumber'], (' (' + p['name'] + ')') if p['name'] else '')})
return [{'value': '', 'label': 'On the machine'}] + options

