if action == 'mount':
	self.mountTool(dict(payload))
	return
changed = payload.get('changeoverAsset')
note = ('; %s set to Changeover' % changed) if changed else ''
result, msg = system.kanoa.tooling.unmount(payload['toolingAssetId'], payload['all'], None, self.view.custom.security.userId)
if msg: system.kanoa.toast.show({'type': 'error', 'message': msg + ((' (%s is in Changeover)' % changed) if changed else '')})
elif payload['all']: system.kanoa.toast.show({'type': 'success', 'message': '%s and its inserts unmounted (fixed inserts stay)%s' % (payload['name'], note)})
else: system.kanoa.toast.show({'type': 'success', 'message': '%s unmounted%s' % (payload['name'], note)})
self.view.custom.refresh = system.date.now()
system.perspective.sendMessage('toolingChanged', {})
return
